<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {api,state} from '../state';import {createLibraryApi,type LibraryRef,type ContentKind,type Visibility} from '../api/libraries';import {errorMessage} from '../api/errors';import DirectoryPicker from '../components/DirectoryPicker.vue';import LibraryGrantEditor from '../components/LibraryGrantEditor.vue';import LibraryArchiveDialog from '../components/LibraryArchiveDialog.vue';
const client=createLibraryApi(api),admin=computed(()=>state.user?.role==='admin'),items=ref<LibraryRef[]>([]),loading=ref(false),error=ref(''),message=ref(''),q=ref(''),page=ref(1),showArchived=ref(false),busy=ref(0),ownerNames=ref<Record<number,string>>({});
const create=ref({name:'',content_kind:'book' as ContentKind,storage_kind:'virtual' as 'virtual'|'directory',visibility:'private' as Visibility,path:''}),creating=ref(false),folder=ref(false),draft=ref<{id:number;name:string;visibility:Visibility}|null>(null),grant=ref<LibraryRef|null>(null),archive=ref<LibraryRef|null>(null);
const filtered=computed(()=>items.value.filter(lib=>(showArchived.value||!lib.archived)&&(!q.value||`${lib.name} ${ownerNames.value[lib.owner_user_id??0]??''}`.toLowerCase().includes(q.value.toLowerCase())))),rows=computed(()=>filtered.value.slice((page.value-1)*20,page.value*20));let epoch=0;
async function load(){const g=++epoch;loading.value=true;error.value='';try{const response=await client.libraries(admin.value,true);if(g!==epoch)return;items.value=admin.value?response.items:response.items.filter(lib=>lib.can_manage);await names()}catch(e){if(g===epoch)error.value=errorMessage(e)}finally{if(g===epoch)loading.value=false}}
async function names(){if(!admin.value)return;const ids=[...new Set(rows.value.map(lib=>lib.owner_user_id).filter((id):id is number=>!!id&&!ownerNames.value[id]))];await Promise.all(ids.map(async id=>{try{ownerNames.value[id]=(await client.user(id)).username}catch{/* a removed owner stays metadata-only */}}))}
async function add(){creating.value=true;error.value='';try{await client.create({name:create.value.name.trim(),content_kind:create.value.content_kind,storage_kind:create.value.storage_kind,visibility:create.value.visibility,...(create.value.storage_kind==='directory'?{path:create.value.path}:{})});create.value={name:'',content_kind:'book',storage_kind:'virtual',visibility:'private',path:''};message.value='书库已创建';await load()}catch(e){error.value=errorMessage(e)}finally{creating.value=false}}
async function save(){if(!draft.value)return;busy.value=draft.value.id;try{await client.update(draft.value.id,{name:draft.value.name.trim(),visibility:draft.value.visibility});draft.value=null;message.value='书库已更新';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=0}}
async function restore(lib:LibraryRef){busy.value=lib.id;try{await client.restore(lib.id);message.value='书库已恢复';await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=0}}
const owner=(lib:LibraryRef)=>lib.owner_user_id===state.user?.id?'我':lib.owner_user_id?ownerNames.value[lib.owner_user_id]||'库所有者':lib.visibility==='shared'?'系统共享':'原所有者已删除';
onMounted(load);
</script>
<template><main class="page library-management"><div class="page-title"><div><h1>{{admin?'书库管理':'我的书库'}}</h1><p>个人库默认私有；管理员维护授权，读取私人内容需要明确阅读权限。</p></div><RouterLink class="button" :to="admin?'/manage':'/'">返回</RouterLink></div><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="message" role="status">{{message}}</p><section class="panel"><h2>新建书库</h2><form @submit.prevent="add"><label>书库名称<input v-model="create.name" required maxlength="80"></label><label>内容类型<select v-model="create.content_kind"><option value="book">图书</option><option value="comic">漫画</option></select></label><label>存储类型<select v-model="create.storage_kind"><option value="virtual">虚拟书库（上传与在线导入）</option><option v-if="admin" value="directory">NAS 目录（只读扫描）</option></select></label><label v-if="create.storage_kind==='directory'">目录<button type="button" @click="folder=true">{{create.path||'选择 NAS 目录'}}</button></label><label>可见性<select v-model="create.visibility"><option value="private">私有</option><option value="restricted">指定授权</option><option value="shared">家庭共享</option></select></label><button :disabled="creating||!create.name.trim()||create.storage_kind==='directory'&&!create.path">{{creating?'创建中…':'创建书库'}}</button></form></section><form class="toolbar" @submit.prevent="page=1;names()"><input v-model="q" placeholder="搜索库名或所有者" aria-label="搜索书库"><button>筛选</button><label class="inline"><input v-model="showArchived" type="checkbox" @change="page=1;names()">显示已归档</label></form><p v-if="loading" role="status">正在读取书库…</p><section v-else class="panel"><p>共 {{filtered.length}} 个书库</p><article v-for="lib in rows" :key="lib.id" class="library-row"><template v-if="draft?.id===lib.id"><label>书库名称<input v-model="draft.name"></label><label>可见性<select v-model="draft.visibility"><option value="private">私有</option><option value="restricted">指定授权</option><option value="shared">家庭共享</option></select></label><button :disabled="!!busy" @click="save">保存修改</button><button :disabled="!!busy" @click="draft=null">取消</button></template><template v-else><div><strong>{{lib.name}}</strong><p>{{lib.content_kind==='comic'?'漫画':'图书'}} · {{lib.storage_kind==='directory'?'NAS 目录':'虚拟书库'}} · {{owner(lib)}} · {{lib.visibility==='shared'?'家庭共享':lib.visibility==='private'?'私有':'指定授权'}} · {{lib.archived?'已归档':'使用中'}}</p><small v-if="!lib.can_read&&!lib.archived">可维护授权；当前账号没有内容阅读权限。</small></div><div class="row-actions"><RouterLink v-if="lib.can_read&&!lib.archived" class="button" :to="{path:lib.content_kind==='comic'?'/comics':'/',query:{library:String(lib.id)}}">打开内容</RouterLink><button v-if="lib.can_manage" @click="draft={id:lib.id,name:lib.name,visibility:lib.visibility}">修改</button><button v-if="lib.can_manage" @click="grant=lib">授权</button><button v-if="lib.can_manage&&lib.archived" :disabled="!!busy" @click="restore(lib)">恢复书库</button><button v-else-if="lib.can_manage" :disabled="!!busy" @click="archive=lib">删除书库</button></div></template></article><p v-if="!rows.length">没有匹配的书库。</p><div v-if="filtered.length>20" class="pagination"><button :disabled="page===1" @click="page--;names()">上一页</button><span>{{page}} / {{Math.ceil(filtered.length/20)}}</span><button :disabled="page*20>=filtered.length" @click="page++;names()">下一页</button></div></section></main><DirectoryPicker v-if="folder" @close="folder=false" @select="create.path=$event;folder=false"/><LibraryGrantEditor v-if="grant" :library="grant" @close="grant=null" @saved="message='授权已保存';load()"/><LibraryArchiveDialog v-if="archive" :library="archive" @close="archive=null" @archived="message='书库已归档，可在显示已归档中恢复';load()"/></template>
<style scoped>.library-management form{max-width:700px}.library-row{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:14px 0;border-bottom:1px solid var(--border);flex-wrap:wrap}.library-row p,.library-row small{font-size:13px;color:var(--muted)}.library-row>div:first-child{min-width:0}.library-row strong{overflow-wrap:anywhere}.library-row .row-actions{flex-wrap:wrap}.inline{display:flex;align-items:center;gap:6px;margin:0}.inline input{width:20px;height:20px}@media(max-width:650px){.library-row>div:first-child{width:100%}.library-row button,.library-row .button{font-size:13px}}
</style>
